/** Fonte única do circuito. As posições foram transcritas das fotografias fornecidas. */
export type ValidationState = 'pending' | 'validated';
export type ViewMode = 'assembly-2d' | 'lab-3d';
export type PinSide = 'left' | 'right' | 'top' | 'bottom';
export type ConnectionCategory = 'power-5v' | 'power-3v3' | 'ground' | 'spi' | 'trig' | 'echo';
export type AssemblyMethod = 'jumper' | 'solder';

export const connectionColors: Record<ConnectionCategory, string> = {
  'power-5v': '#f5a623', 'power-3v3': '#e6674c', ground: '#798898', spi: '#4fb5ff', trig: '#a875ff', echo: '#4dd6a7',
};

export type PhysicalPin = { id: string; label: string; side: PinSide; index: number; local3d: [number, number, number]; description: string; verification: ValidationState };
export type HardwareComponent = {
  id: 'esp32' | 'lora' | 'sensor' | 'level'; name: string; shortName: string; modelStatus: 'parametric-reference'; modelNote: string;
  dimensionsMm: { width: number; height: number; thickness: number; verified: boolean }; boardColor: string; worldPosition: [number, number, number]; threeSize: [number, number]; map: { x: number; y: number; width: number; height: number }; pins: PhysicalPin[];
};
export type AssemblyConnection = {
  id: string; source: { componentId: HardwareComponent['id']; pinId: string }; target: { componentId: HardwareComponent['id']; pinId: string };
  signal: string; category: ConnectionCategory; method: AssemblyMethod; description: string; color: string; validation: ValidationState; validationNote: string;
};
export type AssemblyTask = { id: string; title: string; method: AssemblyMethod; description: string; validation: ValidationState; validationNote: string };

