loraPins.push({ id: 'lora-ant', label: 'ANT', side: 'top', index: 0, local3d: [0.69, 0.11, -0.66], description: 'Pad ANT isolado no canto superior direito; recebe a antena helicoidal por soldagem.', verification: 'validated' });

