'use client';

import dynamic from 'next/dynamic';
import { useEffect, useMemo, useState } from 'react';
import { ArrowLeft, ArrowRight, Camera, Check, ChevronRight, CircleDotDashed, Eye, EyeOff, Focus, Keyboard, Layers3, Maximize2, RotateCcw, Route, ScanLine, TableProperties } from 'lucide-react';
import AssemblyBoard2D from '@/components/AssemblyBoard2D';
import ConnectionTable from '@/components/ConnectionTable';
import { componentById, connections, hardware, pinById, type ViewMode } from '@/lib/assembly-data';

const LabScene = dynamic(() => import('@/components/LabScene'), { ssr: false, loading: () => <div className="lab-loading"><span className="loading-ring" /> Carregando o laboratório 3D…</div> });

export default function Page() {
  const [view, setView] = useState<ViewMode>('assembly-2d');
  const [selectedConnectionId, setSelectedConnectionId] = useState(connections[0].id);
  const [isolate, setIsolate] = useState(false);
  const [reviewed, setReviewed] = useState<string[]>([]);
  const [fullscreen, setFullscreen] = useState(false);
  const selectedIndex = Math.max(0, connections.findIndex((connection) => connection.id === selectedConnectionId));
  const selectedConnection = connections[selectedIndex];
  const sourcePart = componentById(selectedConnection.source.componentId);
  const targetPart = componentById(selectedConnection.target.componentId);
  const sourcePin = pinById(selectedConnection.source.componentId, selectedConnection.source.pinId);
  const targetPin = pinById(selectedConnection.target.componentId, selectedConnection.target.pinId);
  const activePinKeys = useMemo(() => [`${selectedConnection.source.componentId}:${selectedConnection.source.pinId}`, `${selectedConnection.target.componentId}:${selectedConnection.target.pinId}`], [selectedConnection]);

  useEffect(() => { try { const saved = localStorage.getItem('assembly-review'); if (saved) setReviewed(JSON.parse(saved)); } catch { /* Browser storage is optional. */ } }, []);
  useEffect(() => { const onKey = (event: KeyboardEvent) => { if (event.key === 'ArrowRight') setSelectedConnectionId(connections[Math.min(connections.length - 1, selectedIndex + 1)].id); if (event.key === 'ArrowLeft') setSelectedConnectionId(connections[Math.max(0, selectedIndex - 1)].id); if (event.key === '1') setView('assembly-2d'); if (event.key === '2') setView('lab-3d'); if (event.key.toLowerCase() === 'i') setIsolate((value) => !value); }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey); }, [selectedIndex]);

  const selectConnection = (id: string) => setSelectedConnectionId(id);
  const changeConnection = (offset: number) => setSelectedConnectionId(connections[Math.max(0, Math.min(connections.length - 1, selectedIndex + offset))].id);
  const toggleReviewed = () => { const next = reviewed.includes(selectedConnectionId) ? reviewed.filter((id) => id !== selectedConnectionId) : [...reviewed, selectedConnectionId]; setReviewed(next); localStorage.setItem('assembly-review', JSON.stringify(next)); };
  const capture = () => { const canvas = document.querySelector('canvas'); if (!canvas) return; const link = document.createElement('a'); link.href = canvas.toDataURL('image/png'); link.download = `laboratorio-${selectedConnection.id}.png`; link.click(); };

  return <main className={fullscreen ? 'laboratory fullscreen' : 'laboratory'}>
    <header className="lab-header"><div className="lab-brand"><span className="brand-symbol"><Route size={18} /></span><span><b>CIRCUITLAB</b><small>GUIA DE MONTAGEM ORIENTADO POR DADOS</small></span></div><div className="header-audit"><span className="status-dot" /> 0 LIGAÇÕES VALIDADAS <i /> {connections.length} CANDIDATOS PENDENTES</div><div className="header-shortcuts"><Keyboard size={15} /><span><kbd>1</kbd> 2D <kbd>2</kbd> 3D <kbd>←</kbd><kbd>→</kbd> etapa <kbd>I</kbd> isolar</span></div></header>
    <div className="lab-layout">
      <aside className="guide-panel">
        <div className="panel-title"><span className="section-eyebrow">MONTAGEM GUIADA</span><h1>Conexão {String(selectedIndex + 1).padStart(2, '0')}<em>/{String(connections.length).padStart(2, '0')}</em></h1></div>
        <div className="guide-progress"><div><span>REVISÃO VISUAL</span><b>{reviewed.length}/{connections.length}</b></div><i><span style={{ width: `${(reviewed.length / connections.length) * 100}%` }} /></i><small>Marcar aqui não valida a ligação física.</small></div>
        <div className="guide-connection" style={{ '--connection': selectedConnection.color } as React.CSSProperties}>
          <div className="connection-index"><span>ETAPA ATUAL</span><b>{selectedConnection.signal}</b></div>
          <div className="terminal-pair"><div><span>ORIGEM</span><b>{sourcePart.shortName}</b><strong>{sourcePin.label}</strong><small>terminal físico</small></div><ChevronRight size={18} /><div><span>DESTINO</span><b>{targetPart.shortName}</b><strong>{targetPin.label}</strong><small>terminal físico</small></div></div>
          <p>{selectedConnection.description}</p>
        </div>
        <div className="pending-callout"><CircleDotDashed size={17} /><div><b>PENDENTE DE VALIDAÇÃO</b><p>{selectedConnection.validationNote}</p></div></div>
        <button className={`review-button ${reviewed.includes(selectedConnectionId) ? 'reviewed' : ''}`} onClick={toggleReviewed}><span>{reviewed.includes(selectedConnectionId) && <Check size={13} />}</span>{reviewed.includes(selectedConnectionId) ? 'Revisão visual concluída' : 'Marcar revisão visual'}</button>
        <div className="guide-steps"><span className="section-eyebrow">CANDIDATOS DE CONEXÃO</span>{connections.map((connection, index) => <button key={connection.id} className={connection.id === selectedConnectionId ? 'active' : ''} onClick={() => selectConnection(connection.id)}><i style={{ background: connection.color }} /> <span><b>{String(index + 1).padStart(2, '0')} · {connection.signal}</b><small>{connection.validation === 'validated' ? 'validada' : 'aguarda validação'}</small></span>{reviewed.includes(connection.id) && <Check size={14} />}</button>)}</div>
      </aside>
      <section className="work-panel">
        <div className="work-toolbar"><div><span className="section-eyebrow">{view === 'assembly-2d' ? 'MODO MONTAGEM · ORTOGRÁFICO' : 'MODO LABORATÓRIO · WEBGL'}</span><h2>{view === 'assembly-2d' ? 'Mapa de conexões e terminais' : 'Bancada 3D sincronizada'}</h2></div><div className="toolbar-actions"><div className="view-switch" role="tablist"><button className={view === 'assembly-2d' ? 'active' : ''} onClick={() => setView('assembly-2d')}><ScanLine size={15} /> Montagem 2D</button><button className={view === 'lab-3d' ? 'active' : ''} onClick={() => setView('lab-3d')}><Layers3 size={15} /> Laboratório 3D</button></div>{view === 'lab-3d' && <><button className={`tool-button ${isolate ? 'active' : ''}`} onClick={() => setIsolate(!isolate)}>{isolate ? <EyeOff size={15} /> : <Eye size={15} />}{isolate ? 'Ocultando outros' : 'Isolar ligação'}</button><button className="icon-action" title="Capturar laboratório" onClick={capture}><Camera size={17} /></button></>}<button className="icon-action" title="Tela cheia" onClick={() => setFullscreen(!fullscreen)}><Maximize2 size={17} /></button></div></div>
        <div className={`visual-stage ${view}`}>{view === 'assembly-2d' ? <AssemblyBoard2D selectedConnectionId={selectedConnectionId} onSelectConnection={selectConnection} activePinKeys={activePinKeys} /> : <LabScene selectedConnectionId={selectedConnectionId} isolate={isolate} />}{view === 'lab-3d' && <div className="scene-overlay"><span><i className="status-dot" /> FIO 3D ANCORADO A TERMINAIS</span><span>ARRASTE PARA ORBITAR · SCROLL PARA ZOOM</span></div>}</div>
        <div className="selection-summary"><span className="connection-color" style={{ background: selectedConnection.color }} /><div><b>{selectedConnection.signal}</b><small>{sourcePart.shortName} · {sourcePin.label} → {targetPart.shortName} · {targetPin.label}</small></div><span className="validation-chip pending"><CircleDotDashed size={13} /> Pendente de validação</span></div>
        <div className="step-navigation"><button onClick={() => changeConnection(-1)} disabled={selectedIndex === 0}><ArrowLeft size={16} /> Anterior</button><div>{connections.map((connection) => <button key={connection.id} className={connection.id === selectedConnectionId ? 'active' : ''} style={{ background: connection.color }} onClick={() => selectConnection(connection.id)} aria-label={`Selecionar ${connection.signal}`} />)}</div><button onClick={() => changeConnection(1)} disabled={selectedIndex === connections.length - 1}>Próxima <ArrowRight size={16} /></button></div>
      </section>
      <aside className="detail-panel"><div className="panel-title"><span className="section-eyebrow">INSPEÇÃO DA LIGAÇÃO</span><h2>Terminais selecionados</h2></div><div className="pin-card"><span>ORIGEM</span><b>{sourcePart.name}</b><strong>{sourcePin.label}</strong><p>{sourcePin.description}</p></div><div className="wire-arrow"><i style={{ background: selectedConnection.color }} /> <ArrowRight size={15} /> <i style={{ background: selectedConnection.color }} /></div><div className="pin-card"><span>DESTINO</span><b>{targetPart.name}</b><strong>{targetPin.label}</strong><p>{targetPin.description}</p></div><div className="model-audit"><span className="section-eyebrow">FIDELIDADE DO MODELO</span>{[sourcePart, targetPart].map((component) => <div key={component.id}><b>{component.shortName}</b><span>Paramétrico por referência</span><small>{component.dimensionsMm.verified ? 'Dimensão verificada' : 'Dimensões não verificadas'}</small></div>)}</div><button className="reset-selection" onClick={() => { setSelectedConnectionId(connections[0].id); setIsolate(false); }}><RotateCcw size={14} /> Restaurar visualização</button></aside>
    </div>
    <ConnectionTable selectedConnectionId={selectedConnectionId} onSelect={selectConnection} />
    <footer className="lab-footer">Esta aplicação separa posição física, representação visual e validação elétrica. Enquanto a revisão e os datasheets não forem confirmados, nenhum candidato deve ser usado como instrução de montagem.</footer>
  </main>;
}
